mapper.select:
SELECT pro.p_name as pName,eaf.*, COALESCE(cn.cName, '') AS declarationUnitName from Eng_Award_Forecast eaf left join (select eafu.eaf_id,LISTAGG(sc.c_name, ', ') WITHIN GROUP (ORDER BY sc.c_name) AS cName from Eng_Award_Forecast_Unit eafu left join SYS_Company sc ON sc.C_ID = eafu.unit_id GROUP BY eafu.eaf_id) cn ON eaf.id = cn.eaf_id left join pre_project pro on eaf.award_Winning_Project=pro.p_id
and eaf.award_name like concat('%',#{params.awardName},'%')
and eaf.award_type = #{params.awardType}
and eaf.award_level = #{params.awardLevel}
and eaf.award_winning_project=#{params.awardWinningProject}
and likePname(#{params.pName},pro.P_Id)=true
and pro.p_name like concat('%',#{params.pName},'%')
and eaf.award_department like concat('%',#{params.awardDepartment},'%')
and cn.cName like concat('%',#{params.declarationUnitName},'%')

select pro.p_name as pName,eaf.*,COALESCE(cn.cName, '') AS declarationUnitName FROM Eng_Award_Forecast eaf LEFT JOIN(SELECTeafu.eaf_id,GROUP_CONCAT(sc.c_name ORDER BY sc.c_name SEPARATOR ', ') AS cName FROM Eng_Award_Forecast_Unit eafu LEFT JOIN SYS_Company sc ON sc.C_ID = eafu.unit_id GROUP BY eafu.eaf_id) cn ON eaf.id = cn.eaf_id left join pre_project pro on eaf.award_Winning_Project=pro.p_id
and eaf.award_name like concat('%',#{params.awardName},'%')
and eaf.award_type = #{params.awardType}
and eaf.award_level = #{params.awardLevel}
and eaf.award_winning_project=#{params.awardWinningProject}
and likePname(#{params.pName},pro.P_Id)=true
and pro.p_name like concat('%',#{params.pName},'%')
and eaf.award_department like concat('%',#{params.awardDepartment},'%')
and cn.cName like concat('%',#{params.declarationUnitName},'%')
